mapper.select:
select sa.*,sum(sp.seckill_stock) as productCount,mp.shop_name as merchantName from seckill_activity sa left join seckill_product sp on sp.activity_id = sa.id left join merchant_profile mp on sa.merchant_id = mp.user_id
and deleted = 0
and merchant_id = #{merchantId}
and mp.shop_name like concat('%',#{pageQueryBO.merchantName},'%')
and sa.name like concat('%', #{pageQueryBO.keyword}, '%')
and status = #{pageQueryBO.status}
and deleted = #{pageQueryBO.deleted}
group by sa.id
